def max_sum_no_three_consecutive(arr):
    max_sum = float('-inf')
    for i in range(len(arr)):
        temp_sum = arr[i]
        for j in range(i+1, len(arr)):
            if (j - i) < 3:
                temp_sum += arr[j]
            else:
                break
        max_sum = max(max_sum, temp_sum)
    return max_sum

def find_divisible_numbers(start, end):
    divisible_numbers = []
    for num in range(start, end + 1):
        contains_all_digits = True
        for digit in str(num):
            if int(digit) not in str(num):
                contains_all_digits = False
                break
        if contains_all_digits:
            divisible_numbers.append(num)
    return divisible_numbers

