def isIsomorphic(s1, s2):
    if len(s1)!= len(s2):
        return False

    d1 = {}
    d2 = {}

    for i in range(len(s1)):
        if s1[i] not in d1:
            d1[s1[i]] = s2[i]
        else:
            if d1[s1[i]]!= s2[i]:
                return False

        if s2[i] not in d2:
            d2[s2[i]] = s1[i]
        else:
            if d2[s2[i]]!= s1[i]:
                return False

    return True

def find_first_repeated_word(s):
    """
    Returns the first repeated word in the given string, or None if no word is repeated.
    """
    seen = set()
    for word in s.split():
        if word in seen:
            return word
        seen.add(word)
    return None

def largest_palindrome(arr):
    # Write your code here
    max_palindrome = 0
    for i in range(len(arr)):
        for j in range(i, len(arr)):
            if arr[i] == arr[j] and arr[i:j+1] == arr[i:j+1][::-1]:
                if max_palindrome < arr[i:j+1]:
                    max_palindrome = arr[i:j+1]
    return max_palindrome

def find_demlo_number(n):
    # Handle base case: if n is 0, return 1
    if n == 0:
        return 1

    # Otherwise, compute and recurse
    return (2 * n) + find_demlo_number(n // 2)

def find_min(arr):
    if len(arr) == 0:
        return None
    if len(arr) == 1:
        return arr[0]
    if len(arr) == 2:
        return min(arr)
    if arr[0] > arr[1]:
        return arr[0]
    if arr[len(arr) - 1] > arr[len(arr) - 2]:
        return arr[len(arr) - 1]
    return min(arr[1:len(arr) - 1])

